import {STORY_BEATS,BENCH_LESSONS,FIELD_STATIONS,REBUILDS,storyFlag,storyOwns,storyCurrent,syncStoryCampaign,finaleRoster} from './story-campaign.js';
import {aircraftCode} from './fleet-manifest.js';
const esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const title=(label,name)=>`<div class="panelTop"><div><div class="eyebrow">${label}</div><h2>${name}</h2></div></div>`;
export function renderFieldLink(s,{beatId,portrait='',notice=''}={}){
 const c=syncStoryCampaign(s),current=storyCurrent(s),beat=STORY_BEATS.find(b=>b.id===beatId&&b.when(s))||current;
 return title('BLACKLINE / FIELD LINK','Keep the line open')+`<section class="codec"><div class="codecContact"><div class="codecPortrait">${portrait}</div><span class="eyebrow">PORTRAIT LINK / ${beat.speaker==='Charger'?'LOCAL ASSISTANT':'FIELD CONTACT'}</span><h3>${esc(beat.speaker)}</h3><div class="codecWave" aria-hidden="true">${Array.from({length:28},(_,i)=>`<i style="--bar:${10+(i*13%31)}px;--delay:${i*.07}s"></i>`).join('')}</div><span>104.7 MHz · RECORD ${String(STORY_BEATS.indexOf(beat)+1).padStart(2,'0')}</span></div><div class="codecText"><span class="eyebrow">${esc(beat.name)}</span><p>${esc(beat.text)}</p><aside><b>Next field step</b><p>${esc(beat.task)}</p></aside><div class="commandGrid"><button data-story-op="read" data-beat="${beat.id}">${c.read.includes(beat.id)?'MESSAGE READ':'ACKNOWLEDGE'}</button><button data-panel="play">BACK TO THE FIELD</button></div></div></section><details class="storyDetails"><summary>Call log · ${STORY_BEATS.filter(b=>b.when(s)&&!c.read.includes(b.id)).length} unread</summary><div class="storyCallList">${STORY_BEATS.filter(b=>b.when(s)).map(b=>`<button data-story-call="${b.id}" aria-pressed="${b.id===beat.id}"><span>${esc(b.speaker)}</span>${esc(b.name)}${c.read.includes(b.id)?'':' · NEW'}</button>`).join('')}</div></details><section class="chargerCommand"><div><span class="eyebrow">CHARGER / ${esc(c.charger.stage.toUpperCase())}</span><h3>“Charger, find me a power source.”</h3><p>${esc(s.squad?.engineer?.task?.reason||'Build Utility and decode the Relay House to dispatch. A loaded pack turns the mission into Harvest & Deliver.')}</p></div><div class="commandGrid"><button class="primary" data-story-op="charger">FIND ME A POWER SOURCE</button><button data-story-op="stage-line">LEAVE CHARGER ON THE LINE</button><button data-story-op="recall" data-aircraft="engineer" ${c.stations.engineer?'':'disabled'}>RECALL STATIONED CHARGER</button></div></section><p class="storyNotice" role="status">${esc(notice)}</p><div class="commandGrid"><button data-nav="fleetNetwork">FLEET NETWORK</button><button data-nav="fieldBench">FIELD BENCH</button><button data-nav="fieldDiscoveries">SENSOR DISCOVERIES</button><button data-nav="story">STORY ARCHIVE</button></div><p class="hint">${c.mode==='story'?'Story expedition · tools and airframes are earned in the field.':'Legacy expedition · your existing fleet and tools are retained.'} Field link pauses the expedition. Resume to fly or charge.</p>`;
}
export function renderFieldBench(s,{notice='',lessonId='circuit',near=false}={}){
 const c=syncStoryCampaign(s),l=BENCH_LESSONS.find(l=>l.id===lessonId)||BENCH_LESSONS[0],ready=storyFlag(s,l.requires);
 return title('FIELD TOOL / REPAIR & LEARNING','Make it work again')+`<p class="lead">A repaired board. A known reading. One more aircraft that gets to fly.</p><div class="benchLayout"><nav aria-label="Field exercises">${BENCH_LESSONS.map(p=>`<button data-bench-lesson="${p.id}" aria-pressed="${p.id===l.id}">${esc(p.name)}<small>${c.lessons.includes(p.id)?'RECORDED':storyFlag(s,p.requires)?'AVAILABLE':'RECOVER IN THE FIELD'}</small></button>`).join('')}</nav><section class="benchReading"><span class="eyebrow">${c.lessons.includes(l.id)?'VERIFIED FIELD NOTE':'PRACTICE INSTRUMENT'}</span><h3>${esc(l.name)}</h3><p>${ready?esc(l.question):'Recover this note as you restore the camps, Relay House and waterworks.'}</p>${ready?`<label for="benchValue">Your reading (${esc(l.unit)})</label><div class="benchInput"><input id="benchValue" type="number" inputmode="decimal" step="any" autocomplete="off"><button data-story-op="solve" data-lesson="${l.id}">CHECK READING</button></div><details><summary>Work it through</summary><p>${esc(l.hint)}</p></details>${c.lessons.includes(l.id)?`<p>${esc(l.explain)}</p>`:''}<a href="${l.source}" target="_blank" rel="noopener noreferrer">Read the source ↗</a>`:''}</section></div><p class="storyNotice" role="status">${esc(notice)}</p><h3>Recovered frames</h3><p class="hint">${near?'Workbench in reach.':'Stop beside your trailer or an unlocked field station to assemble a frame.'} These are your campaign aircraft; rebuilt frames keep their own hull and battery.</p><div class="rebuildList">${REBUILDS.map(r=>`<article><div><h3>${esc(r.name)}</h3><p>${esc(r.clue)}</p><small>${Object.entries(r.cost).map(([k,n])=>n+' '+k).join(' · ')}</small></div><button data-story-op="rebuild" data-aircraft="${r.id}" ${c.owned.includes(r.id)?'disabled':''}>${c.owned.includes(r.id)?'IN YOUR FLEET':'REBUILD'}</button></article>`).join('')}</div>`;
}
export function renderFleetNetwork(s,{notice=''}={}){
 const c=syncStoryCampaign(s);
 return title('DISTRIBUTED FLEET / FIELD STATIONS','The map is your hangar')+`<p class="lead">Leave an aircraft where it matters. Return for it when you need it.</p><p class="hint">Select an aircraft in Fleet, dock it, then stop with the bike beside a station to place it. Station reserves are finite. Other sectors and closed sessions do not advance charging.</p><div class="networkRoster">${Object.entries(c.stations).map(([id,p])=>`<article><b>${esc(aircraftCode(id))}</b><span>${esc(p.name)} · Sector ${p.leg}</span><span>${Math.round(s.squad[id]?.battery||0)}% battery · ${Math.round(s.squad[id]?.system.hp||0)}% hull</span><button data-story-op="recall" data-aircraft="${id}">${p.leg===s.leg?'RETRIEVE / RECALL':'RETURN TO SECTOR '+p.leg+' FIRST'}</button></article>`).join('')||'<p>No aircraft stationed yet. Your travelling fleet stays with the rig.</p>'}</div><div class="stationList">${FIELD_STATIONS.map(p=>`<article><div><span class="eyebrow">SECTOR ${p.leg} / ${storyFlag(s,p.requires)?'AVAILABLE':'UNRESTORED'}</span><h3>${esc(p.name)}</h3><p>${Math.round(c.reserves[p.id])} / ${p.capacity} Wh · ${p.x} E / ${Math.abs(p.z)} N</p></div><button data-story-op="place" data-site="${p.id}" ${p.leg!==s.leg||!storyFlag(s,p.requires)?'disabled':''}>PLACE ${esc(aircraftCode(s.droneType))}</button></article>`).join('')}</div><details class="storyDetails"><summary>Ride between cleared sectors</summary><p>Stop at an unlocked station with all travelling aircraft docked. Each trip spends 8% bike charge. Stationed drones remain in place.</p><div class="commandGrid">${[[1,'Ghost Signal'],[2,'The Spillway'],[3,'Black Start']].map(([leg,name])=>`<button data-story-op="travel" data-leg="${leg}" ${s.leg===leg||leg===2&&!s.won||leg===3&&!s.leg2Won?'disabled':''}>${name}</button>`).join('')}</div></details><p class="storyNotice" role="status">${esc(notice)}</p>`;
}
export function renderFleetFinale(s,{notice=''}={}){
 const ids=finaleRoster(s),c=syncStoryCampaign(s);
 return title('BLACK START / THE SKY BELONGS TO YOU','All the lights we carried')+`<section class="finaleCard"><span class="eyebrow">${s.leg3Won?'TRANSMISSION RECEIVED':'REACH THE BLACK START CORE'}</span><h3>${s.leg3Won?'For once, the energy can be for joy.':'Every repair is a light you might see again.'}</h3><p>Your own surviving, charged aircraft perform this show in the current world. Parked aircraft stay at their stations until you collect them. No replacement swarm is created.</p><p><b>${ids.length} available:</b> ${ids.map(aircraftCode).join(' · ')||'Recall and charge your fleet first.'}</p><div class="commandGrid"><button class="primary" data-story-op="finale" ${s.leg3Won&&ids.length?'':'disabled'}>LAUNCH MY FLEET SHOW</button><button data-nav="swarmProgram" ${s.leg3Won?'':'disabled'}>DRAW / SCRIPT MY SHOW</button><button data-story-op="stop-show">END SHOW & RECALL</button></div><p>${c.finale.runs} shows begun · ${c.finale.participants.length} aircraft in the last cast</p></section><p class="storyNotice" role="status">${esc(notice)}</p><details class="storyDetails"><summary>After the transmission</summary><p>Return to earlier stations, recover aircraft, rebuild spare frames and make a different show. Fleet Commander and the hidden F9 fleet test remain available for unrestricted experiments.</p><p>Picture imports, uploaded music analysis and worldwide convergence are later campaign work. Current choreography supports scripts, mathematical fields, words, drawing and manual beat controls in Commander.</p><a href="./CAMPAIGN-ARC.md" target="_blank">Open the full campaign direction ↗</a></details>`;
}
